import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    system = platform.system().lower()
    records = []
    start_time = time.time()
    while True:
        now = time.time()
        elapsed = now - start_time
        if elapsed > duration and records:
            break
        if system.startswith("win"):
            try:
                proc = subprocess.Popen(["wmic", "cpu", "get", "loadpercentage", "/value"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                out, err = proc.communicate()
                if proc.returncode != 0:
                    cpu_usage = None
                else:
                    text = out.decode(errors="ignore")
                    cpu_usage = None
                    for line in text.splitlines():
                        line = line.strip()
                        if line.lower().startswith("loadpercentage"):
                            parts = line.split("=", 1)
                            if len(parts) == 2:
                                try:
                                    cpu_usage = float(parts[1].strip())
                                except ValueError:
                                    cpu_usage = None
                            break
            except Exception:
                cpu_usage = None
        else:
            try:
                proc = subprocess.Popen(["top", "-bn1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
                out, err = proc.communicate()
                if proc.returncode != 0:
                    cpu_usage = None
                else:
                    text = out.decode(errors="ignore")
                    cpu_usage = None
                    for line in text.splitlines():
                        if "Cpu(s)" in line or "CPU:" in line:
                            l = line.replace(",", " ")
                            parts = l.split()
                            us = sy = ni = None
                            for p in parts:
                                if p.endswith("us"):
                                    try:
                                        us = float(p[:-2])
                                    except ValueError:
                                        us = None
                                if p.endswith("sy"):
                                    try:
                                        sy = float(p[:-2])
                                    except ValueError:
                                        sy = None
                                if p.endswith("ni"):
                                    try:
                                        ni = float(p[:-2])
                                    except ValueError:
                                        ni = None
                            if us is not None or sy is not None or ni is not None:
                                us = us or 0.0
                                sy = sy or 0.0
                                ni = ni or 0.0
                                cpu_usage = us + sy + ni
                            break
            except Exception:
                cpu_usage = None
        records.append({"timestamp": now, "cpu_usage": cpu_usage})
        time.sleep(interval)
        if time.time() - start_time >= duration:
            break
    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as f:
            json.dump(records, f)
    except OSError:
        return None
    return LOGFILE_PATH
